import { Component, Input, Output, EventEmitter } from '@angular/core';

interface RequestStartedPayload {
  method: 'GET' | 'POST';
  path: string;
}

interface RequestSucceededPayload {
  status: number;
  duration_ms: number;
}

interface RequestFailedPayload {
  reason: 'timeout' | 'network' | 'http_4xx' | 'http_5xx';
  status: number;
}

@Component({
  selector: 'app-http-api-client',
  standalone: true,
  template: `
    <div class="http-api-client">
      <h3>HTTP-API-Client</h3>
      <div class="row"><label>base_url:</label><span>{{ base_url }}</span></div>
      <div class="row"><label>timeout_ms:</label><span>{{ timeout_ms }}</span></div>
      <div class="row"><label>max_retries:</label><span>{{ max_retries }}</span></div>
      <div class="row"><label>auth_token:</label><span>{{ auth_token ? '***' : '(none)' }}</span></div>
    </div>
  `,
  styles: [`
    .http-api-client {
      font-family: sans-serif;
      padding: 0.75rem;
      border: 1px solid #ccc;
      border-radius: 4px;
    }
    .http-api-client h3 {
      margin: 0 0 0.5rem 0;
      font-size: 1rem;
    }
    .row {
      display: flex;
      gap: 0.5rem;
      font-size: 0.875rem;
      padding: 0.125rem 0;
    }
    .row label {
      font-weight: 600;
      min-width: 6rem;
    }
  `]
})
export class HttpApiClientComponent {
  @Input() base_url: string = '';
  @Input() timeout_ms: number = 10000;
  @Input() max_retries: number = 3;
  @Input() auth_token?: string;

  @Output() request_started = new EventEmitter<RequestStartedPayload>();
  @Output() request_succeeded = new EventEmitter<RequestSucceededPayload>();
  @Output() request_failed = new EventEmitter<RequestFailedPayload>();

  async get(path: string): Promise<{ status: number; body?: unknown }> {
    return this.request('GET', path);
  }

  async post(path: string, body?: unknown): Promise<{ status: number; body?: unknown }> {
    return this.request('POST', path, body);
  }

  private async request(
    method: 'GET' | 'POST',
    path: string,
    body?: unknown
  ): Promise<{ status: number; body?: unknown }> {
    this.request_started.emit({ method, path });

    const url = this.joinUrl(this.base_url, path);
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (this.auth_token) {
      headers['Authorization'] = `Bearer ${this.auth_token}`;
    }

    let attempt = 0;
    let lastStatus = 0;
    let lastReason: 'timeout' | 'network' | 'http_4xx' | 'http_5xx' = 'network';

    while (attempt <= this.max_retries) {
      const start = Date.now();
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.timeout_ms);

      try {
        const res = await fetch(url, {
          method,
          headers,
          body: body !== undefined ? JSON.stringify(body) : undefined,
          signal: controller.signal
        });
        clearTimeout(timeoutId);
        const duration_ms = Date.now() - start;
        lastStatus = res.status;

        if (res.status >= 200 && res.status < 300) {
          this.request_succeeded.emit({ status: res.status, duration_ms });
          let responseBody: unknown;
          try { responseBody = await res.json(); } catch { responseBody = undefined; }
          return { status: res.status, body: responseBody };
        }

        if (res.status >= 500 && res.status < 600) {
          lastReason = 'http_5xx';
        } else if (res.status >= 400 && res.status < 500) {
          lastReason = 'http_4xx';
          this.request_failed.emit({ reason: lastReason, status: res.status });
          return { status: res.status };
        } else {
          lastReason = 'network';
        }
      } catch (err: unknown) {
        clearTimeout(timeoutId);
        if (err instanceof Error && err.name === 'AbortError') {
          lastReason = 'timeout';
        } else {
          lastReason = 'network';
        }
        lastStatus = 0;
      }

      if (attempt === this.max_retries) {
        break;
      }
      const backoff = Math.pow(2, attempt) * 100;
      await new Promise(resolve => setTimeout(resolve, backoff));
      attempt++;
    }

    this.request_failed.emit({ reason: lastReason, status: lastStatus });
    return { status: lastStatus };
  }

  private joinUrl(base: string, path: string): string {
    if (!base) return path;
    if (base.endsWith('/') && path.startsWith('/')) {
      return base + path.substring(1);
    }
    if (!base.endsWith('/') && !path.startsWith('/')) {
      return `${base}/${path}`;
    }
    return base + path;
  }
}
